definition:
strict graph FD {
 layout=fdp;
 nodesep=0.4; esep=0.2;
 node [shape=doublecircle peripheries=3 style=filled fillcolor="#e0e8ff" fontcolor="#001040"];
 { rank=same; r1; r2; r3; }
 hidden [style=invis];
 r1 -- r2 [constraint=false];
 r2 -- r3;
 r3 -- r1 [len=2.0];
 r1 -- hub;
 hub -- hidden;
 hub [peripheries=1 fillcolor="#ffd0d0"];
 r1 -- r2;
}
